function perfectpixel_is_hidden_product( $product_id ) {
	$product = wc_get_product( $product_id );
	return $product && 'hidden' === $product->get_catalog_visibility();
}

function perfectpixel_hide_hidden_cart_item( $visible, $cart_item ) {
	return perfectpixel_is_hidden_product( $cart_item['product_id'] ) ? false : $visible;
}

function perfectpixel_hide_hidden_order_item( $visible, $item ) {
	return is_callable( array( $item, 'get_product_id' ) ) && perfectpixel_is_hidden_product( $item->get_product_id() ) ? false : $visible;
}
